import{_ as a,o as e,c as d,ae as r}from"./chunks/framework.Co1PSFSm.js";const A=JSON.parse('{"title":"指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide.md","filePath":"guide.md"}'),o={name:"guide.md"};function n(l,t,i,h,s,u){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="指南" tabindex="-1">指南 <a class="header-anchor" href="#指南" aria-label="Permalink to &quot;指南&quot;">​</a></h1><h2 id="这是什么" tabindex="-1">这是什么？ <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么？&quot;">​</a></h2><p><strong>AI 评测编年史</strong>记录了大语言模型（LLM）与 AI Agent 领域中评测技术的发展历程。从 2018 年 GLUE 基准开创多任务评估范式，到 2025 年 Humanity&#39;s Last Exam 试图定义 AI 能力的终极天花板——每一个评测基准都在回答同一个问题：</p><blockquote><p>AI 现在能做什么？还不能做什么？</p></blockquote><h2 id="为什么关注评测" tabindex="-1">为什么关注评测？ <a class="header-anchor" href="#为什么关注评测" aria-label="Permalink to &quot;为什么关注评测？&quot;">​</a></h2><p>评测基准是 AI 领域的&quot;标尺&quot;。它们：</p><ul><li><strong>定义能力边界</strong> —— 一个模型说自己&quot;很强&quot;毫无意义，但说&quot;MMLU 90 分&quot;或&quot;SWE-bench 50%&quot;就有了可比较的参照</li><li><strong>驱动技术发展</strong> —— GSM8K 催生了 Chain-of-Thought，HumanEval 推动了代码生成，SWE-bench 引爆了 AI Agent</li><li><strong>暴露真实问题</strong> —— TruthfulQA 揭示了幻觉问题，ARC-AGI 证明了当前 AI 在抽象推理上的短板</li></ul><h2 id="评测分类" tabindex="-1">评测分类 <a class="header-anchor" href="#评测分类" aria-label="Permalink to &quot;评测分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类别</th><th>代表评测</th><th>核心考察</th></tr></thead><tbody><tr><td>通用能力</td><td>MMLU, HELM, LiveBench</td><td>世界知识、多学科理解</td></tr><tr><td>推理与数学</td><td>GSM8K, MATH, ARC-AGI</td><td>逻辑推理、数学证明、抽象思维</td></tr><tr><td>代码能力</td><td>HumanEval, SWE-bench</td><td>代码生成、软件工程、Bug 修复</td></tr><tr><td>Agent 能力</td><td>AgentBench, GAIA, WebArena</td><td>工具使用、多步规划、环境交互</td></tr><tr><td>对话与偏好</td><td>Chatbot Arena, MT-Bench</td><td>人类偏好对齐、多轮对话质量</td></tr><tr><td>安全与对齐</td><td>TruthfulQA, SimpleQA</td><td>真实性、幻觉率、安全性</td></tr><tr><td>中文评测</td><td>C-Eval, CMMLU</td><td>中文语言理解、中国文化知识</td></tr><tr><td>多模态</td><td>MMMU</td><td>视觉-语言跨模态理解</td></tr></tbody></table><h2 id="状态说明" tabindex="-1">状态说明 <a class="header-anchor" href="#状态说明" aria-label="Permalink to &quot;状态说明&quot;">​</a></h2><ul><li>🟢 <strong>活跃</strong> —— 当前被广泛使用，是模型比较的主流基准</li><li>🔵 <strong>经典</strong> —— 具有历史意义，仍被引用但已不是最前沿的评测标准</li><li>⚪ <strong>已被超越</strong> —— 大多数模型已接近或达到天花板，评测区分度不足</li></ul><h2 id="如何贡献" tabindex="-1">如何贡献 <a class="header-anchor" href="#如何贡献" aria-label="Permalink to &quot;如何贡献&quot;">​</a></h2><p>欢迎提交 PR 补充新的评测基准或更新现有信息。</p>',13)])])}const g=a(o,[["render",n]]);export{A as __pageData,g as default};
